<?xml version="1.0" encoding="UTF-8"?>
<map:businessObjectMap xmlns:MasterpieceInfo="http://dto.rand.chubb.com" xmlns:MasterpieceInfoToRatingTerritoryMap="http://LocationServices/LOC3X3" xmlns:MasterpieceTerritoryInformation="http://cpi/core/masterpiece_territory" xmlns:map="http://www.ibm.com/xmlns/prod/websphere/wbiserver/map/6.0.0" targetNamespace="http://LocationServices/LOC3X3">
  <map:name>MasterpieceInfoToRatingTerritoryMap</map:name>
  <map:inputBusinessObjectVariable businessObjectRef="MasterpieceInfo:MasterpieceInfo" name="MasterpieceInfo"/>
  <map:outputBusinessObjectVariable businessObjectRef="MasterpieceTerritoryInformation:MasterpieceTerritoryInformation" name="MasterpieceTerritoryInformation"/>
  <map:propertyMap executionOrder="1">
    <map:move>
      <map:input businessObjectVariableRef="MasterpieceInfo" property="masterpieceTerritoryCode"/>
      <map:output businessObjectVariableRef="MasterpieceTerritoryInformation" property="MasterpieceTerritoryCode"/>
    </map:move>
  </map:propertyMap>
  <map:propertyMap executionOrder="2">
    <map:move>
      <map:input businessObjectVariableRef="MasterpieceInfo" property="altMasterpieceTerritoryCode"/>
      <map:output businessObjectVariableRef="MasterpieceTerritoryInformation" property="AlternateMasterpieceTerritoryCode"/>
    </map:move>
  </map:propertyMap>
  <map:propertyMap executionOrder="3">
    <map:move>
